targets.source:
count(count by (node, gpu, UUID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster"}
))

count by (node) (
  count by (node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster"}
  )
)

avg by (node,gpu,UUID,modelName) (
  ${MetricPrefix:raw}DCGM_FI_DEV_GPU_UTIL{
    bcs_cluster_id="$Cluster"
  }
)

avg by (node, gpu, UUID, modelName) (
  avg_over_time(${MetricPrefix:raw}DCGM_FI_DEV_GPU_UTIL{bcs_cluster_id="$Cluster"}[60m])
) < 25

100 * avg by (node, gpu, UUID, GPU_I_ID, GPU_I_PROFILE, namespace, pod_name) (
  ${MetricPrefix:raw}DCGM_FI_PROF_PIPE_TENSOR_ACTIVE{
    bcs_cluster_id="$Cluster",
    GPU_I_ID!=""
  }
)

100 * avg by (node, gpu, UUID, GPU_I_ID, GPU_I_PROFILE, namespace, pod_name) (
  ${MetricPrefix:raw}DCGM_FI_PROF_DRAM_ACTIVE{
    bcs_cluster_id="$Cluster",
    GPU_I_ID!=""
  }
)

avg by (node, gpu, UUID, GPU_I_ID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster", pod_name=""}
)

count(count by (node, gpu, UUID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_GPU_UTIL{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
))

avg(avg by (node, gpu, UUID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_GPU_UTIL{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
))

sum(max by (node, gpu, UUID, GPU_I_ID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
))

sum(max by (node, gpu, UUID, GPU_I_ID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_FREE{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
))

sum(max by (node, gpu, UUID, GPU_I_ID) (
  ${MetricPrefix:raw}DCGM_FI_DEV_FB_RESERVED{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
))

100 * sum(max by (node, gpu, UUID, GPU_I_ID) (${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"})) / (
  sum(max by (node, gpu, UUID, GPU_I_ID) (${MetricPrefix:raw}DCGM_FI_DEV_FB_USED{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"})) + sum(max by (node, gpu, UUID, GPU_I_ID) (${MetricPrefix:raw}DCGM_FI_DEV_FB_FREE{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}))
)

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_GPU_TEMP{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_MEMORY_TEMP{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_ENC_UTIL{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_DEC_UTIL{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

sum by (namespace, pod_name) (
  max by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_POWER_USAGE{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

sum by (namespace, pod_name) (
  max by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
) / 1000

sum by (namespace, pod_name) (
  max by (namespace, pod_name, node, gpu, UUID) (
    increase(${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}[5m])
  )
) / 1000

sum by (namespace, pod_name) (
  max by (namespace, pod_name, node, gpu, UUID) (
    increase(${MetricPrefix:raw}DCGM_FI_DEV_TOTAL_ENERGY_CONSUMPTION{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}[1h])
  )
) / 3600000000

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_SM_CLOCK{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

avg by (namespace, pod_name) (
  avg by (namespace, pod_name, node, gpu, UUID) (
    ${MetricPrefix:raw}DCGM_FI_DEV_MEM_CLOCK{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}
  )
)

sum by (namespace, pod_name) (
  max by (namespace, pod_name, node, gpu, UUID) (
    increase(${MetricPrefix:raw}DCGM_FI_DEV_PCIE_REPLAY_COUNTER{bcs_cluster_id="$Cluster", namespace=~"^($Namespace)$", pod_name=~"^($Pod)$"}[1h])
  )
)
